:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #9a9ab0;
  --focus: #f5c542;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  line-height: 1.5;
}

.card {
  width: 100%;
  max-width: 420px;
  background: var(--card);
  border: 4px solid var(--accent);
  border-radius: 0;
  padding: 28px 24px;
  text-align: center;
  box-shadow: 8px 8px 0 #0f0f1f;
}

h1 {
  margin: 0 0 12px;
  font-size: 1.5rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
}

.score-line {
  margin: 0 0 16px;
  color: var(--muted);
  font-size: 1rem;
}

#score { color: var(--text); font-weight: 700; }

.question {
  margin: 0 0 24px;
  font-size: 1.6rem;
  font-weight: 700;
  min-height: 2.4em;
  display: flex;
  align-items: center;
  justify-content: center;
}

.answers, .controls {
  display: flex;
  gap: 12px;
  margin-bottom: 16px;
}

.answers button { flex: 1; }

button {
  flex: 1;
  padding: 14px 12px;
  font-family: inherit;
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--text);
  background: #0f3460;
  border: 3px solid var(--muted);
  border-radius: 0;
  cursor: pointer;
  transition: transform 0.05s, background 0.15s, border-color 0.15s;
}

button:hover:not(:disabled) {
  background: #1a4a7a;
  border-color: var(--accent);
}

button:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

button:active:not(:disabled) {
  transform: translate(2px, 2px);
  background: var(--accent);
}

button:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

#next { background: var(--accent); border-color: var(--accent); }
#next:hover:not(:disabled) { background: #ff5c7a; }

#restart { background: transparent; border-color: var(--muted); }
#restart:hover:not(:disabled) { background: #0f3460; }

@media (max-width: 400px) {
  body { font-size: 16px; }
  .card { padding: 20px 16px; }
  .question { font-size: 1.4rem; }
}

const questionEl = document.getElementById('question');
const answerA = document.getElementById('answer-a');
const answerB = document.getElementById('answer-b');
const scoreEl = document.getElementById('score');
const nextBtn = document.getElementById('next');
const restartBtn = document.getElementById('restart');

const QUESTIONS = [
  { text: '2 + 2 = ?', a: '4', b: '5', correct: 'a' },
  { text: '3 + 3 = ?', a: '5', b: '6', correct: 'b' }
];

let current = 0;
let score = 0;
let locked = false;

function render() {
  const q = QUESTIONS[current];
  questionEl.textContent = q.text;
  answerA.textContent = q.a;
  answerB.textContent = q.b;
  answerA.setAttribute('aria-label', 'Answer A: ' + q.a);
  answerB.setAttribute('aria-label', 'Answer B: ' + q.b);
  scoreEl.textContent = String(score);
  locked = false;
  answerA.disabled = false;
  answerB.disabled = false;
  nextBtn.disabled = false;
}

function choose(choice) {
  if (locked) return;
  locked = true;
  answerA.disabled = true;
  answerB.disabled = true;
  if (choice === QUESTIONS[current].correct) {
    score += 1;
    scoreEl.textContent = String(score);
  }
}

answerA.addEventListener('click', () => choose('a'));
answerB.addEventListener('click', () => choose('b'));

nextBtn.addEventListener('click', () => {
  if (!locked) return;
  if (current === 0) {
    current = 1;
    render();
  } else {
    questionEl.textContent = 'Finished';
    locked = true;
    answerA.disabled = true;
    answerB.disabled = true;
    nextBtn.disabled = true;
  }
});

restartBtn.addEventListener('click', () => {
  current = 0;
  score = 0;
  render();
});

render();
